public enum SceneEnvironmentArchitecture
{
    TrainingLab, MaintenanceBay, WarehouseHall, LoadingCanopy,
    WashdownHall, MachineHall, UtilityAnnex, OutdoorYard,
    RoadCorridor, Waterfront, PublicService, Gallery,
}

/// <summary>
/// Explicit presentation direction, not process or circulation design. Dimensions
/// enlarge context outside the protected process/standing envelope, never move it.
/// Windows: 0 none, 1 high rear slot, 2 sidelight, 3 paired rear, 4 corner clerestory.
/// Portals: 0 none, 1 rear service, 2 wide side, 3 rear loading, 4 side personnel.
/// Roof: 0 open, 1 rear canopy, 2 side soffit, 3 clerestory, 4 corner beam.
/// Supports: 0 none, 1 rear outboard posts, 2 side posts, 3 corner pilasters, 4 split bays.
/// Builder family constraints may further restrict openings to preserve field views.
/// Bench/cabinet colors apply only to passive support, never functional equipment.
/// </summary>
public sealed record SceneEnvironmentArtDirection(
    SceneEnvironmentArchitecture Architecture, string LocationLabel, string LayoutVariant,
    string FloorHex, string WallHex, string AccentHex,
    float WidthScale = 1, float DepthScale = 1, float WallHeight = 3.6f,
    int WindowArrangement = 0, int PortalArrangement = 0,
    int RoofArrangement = 0, int SupportArrangement = 0,
    string PassiveContext = "", string FloorStyle = "concrete", string WallStyle = "paint",
    string BenchTopHex = "", string BenchTopStyle = "", string SupportHex = "", string CabinetHex = "");

