    public static bool TryGet(string sceneId, out SceneEnvironmentArtDirection direction) =>
        Directions.TryGetValue(sceneId, out direction!);

    public static SceneEnvironmentArtDirection ForScene(string sceneId) =>
        Directions.TryGetValue(sceneId, out var direction) ? direction
            : throw new KeyNotFoundException($"No authored environment art direction for scene '{sceneId}'.");
}

